        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" value="@Entry.Relationship"
                   @onchange="e => Update(Entry with { Relationship = e.Value?.ToString() ?? string.Empty })" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Entry.Email"
                   @onchange="e => Update(Entry with { Email = e.Value?.ToString() ?? string.Empty })" />
