toolArgs.file_text:
.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
}

.step-item {
    flex: 1;
    text-align: center;
    position: relative;
}

.step-item:not(:last-child)::after {
    content: '';
    position: absolute;
    top: 18px;
    left: 55%;
    width: 90%;
    height: 2px;
    background: #e0e0e0;
}

.step-item.completed:not(:last-child)::after {
    background: #4caf50;
}

.step-button {
    display: inline-flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    background: none;
    border: none;
    cursor: default;
    padding: 0.5rem;
    font-size: 0.85rem;
    color: #999;
    position: relative;
    z-index: 1;
}

.step-button.completed {
    cursor: pointer;
    color: #4caf50;
}

.step-button.active {
    color: #1976d2;
    font-weight: 600;
}

.step-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: #e0e0e0;
    color: #666;
    font-weight: 600;
}

.completed .step-icon {
    background: #4caf50;
    color: white;
}

.active .step-icon {
    background: #1976d2;
    color: white;
}

.step-label {
    white-space: nowrap;
    font-size: 0.75rem;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h3 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #333;
}

.step-description {
    color: #666;
    margin-bottom: 1rem;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
    color: #444;
    font-size: 0.9rem;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #1976d2;
    box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.1);
}

.form-row {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
}

.form-row .form-group {
    flex: 1;
    min-width: 200px;
}

.checkbox-group {
    display: flex;
    align-items: end;
    padding-bottom: 0.5rem;
}

.checkbox-group label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal;
}

.checkbox-group input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

.btn-primary {
    background: #1976d2;
    color: white;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font-size: 0.95rem;
    cursor: pointer;
    font-weight: 500;
}

.btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-outline {
    background: white;
    color: #1976d2;
    border: 1px solid #1976d2;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font-size: 0.95rem;
    cursor: pointer;
}

.btn-outline:hover {
    background: #e3f2fd;
}

.btn-secondary {
    background: #f5f5f5;
    color: #333;
    border: 1px solid #ccc;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    cursor: pointer;
    margin-bottom: 1rem;
}

.btn-secondary:hover {
    background: #eee;
}

.btn-remove {
    background: none;
    border: none;
    color: #d32f2f;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-remove:hover {
    text-decoration: underline;
}

.btn-link {
    background: none;
    border: none;
    color: #1976d2;
    cursor: pointer;
    font-size: 0.85rem;
    text-decoration: underline;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1.05rem;
}

/* Work Entry & Reference Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.work-entry-header,
.reference-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h4,
.reference-header h4 {
    margin: 0;
    font-size: 1rem;
    color: #555;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 200px;
    resize: vertical;
}

.char-count {
    text-align: right;
    font-size: 0.8rem;
    color: #888;
    margin-top: 0.25rem;
}

.char-count.warning {
    color: #e65100;
}

/* Validation */
.validation-error {
    background: #ffebee;
    color: #c62828;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin: 1rem 0;
    font-size: 0.9rem;
}

.field-error {
    color: #c62828;
    font-size: 0.8rem;
    margin-top: 0.25rem;
    display: block;
}

/* Review Step */
.review-section {
    border-bottom: 1px solid #eee;
    padding-bottom: 1.25rem;
    margin-bottom: 1.25rem;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h4 {
    margin: 0;
    color: #333;
}

.review-section dl {
    display: grid;
    grid-template-columns: 100px 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #666;
}

.review-section dd {
    margin: 0;
}

.review-work-entry {
    margin-bottom: 0.75rem;
    padding-left: 0.5rem;
    border-left: 3px solid #e0e0e0;
}

.review-dates {
    font-size: 0.85rem;
    color: #666;
}

.review-description {
    margin: 0.25rem 0 0;
    font-size: 0.9rem;
    color: #555;
}

.review-reference {
    margin-bottom: 0.5rem;
}

.review-cover-letter {
    white-space: pre-wrap;
    background: #f9f9f9;
    padding: 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 2rem;
}

.submission-confirmation h4 {
    color: #4caf50;
    font-size: 1.4rem;
}

