+    border: none;
+    color: #d32f2f;
+    cursor: pointer;
+    font-size: 0.85rem;
+}
+
+.btn-remove:hover {
+    text-decoration: underline;
+}
+
+.btn-link {
+    background: none;
+    border: none;
+    color: #1976d2;
+    cursor: pointer;
+    font-size: 0.85rem;
+    text-decoration: underline;
+}
+
+.btn-submit {
+    padding: 0.75rem 2rem;
+    font-size: 1.05rem;
+}
+
+/* Work Entry & Reference Cards */
+.work-entry-card,
+.reference-card {
+    border: 1px solid #e0e0e0;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+    background: #fafafa;
+}
+
+.work-entry-header,
+.reference-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 1rem;
+}
+
+.work-entry-header h4,
+.reference-header h4 {
+    margin: 0;
+    font-size: 1rem;
+    color: #555;
+}
+
+/* Cover Letter */
+.cover-letter-textarea {
+    min-height: 200px;
+    resize: vertical;
+}
+
+.char-count {
+    text-align: right;
+    font-size: 0.8rem;
+    color: #888;
+    margin-top: 0.25rem;
+}
+
+.char-count.warning {
+    color: #e65100;
+}
+
+/* Validation */
+.validation-error {
+    background: #ffebee;
+    color: #c62828;
+    padding: 0.75rem 1rem;
+    border-radius: 4px;
+    margin: 1rem 0;
+    font-size: 0.9rem;
+}
+
+.field-error {
+    color: #c62828;
+    font-size: 0.8rem;
+    margin-top: 0.25rem;
+    display: block;
+}
+
+/* Review Step */
+.review-section {
+    border-bottom: 1px solid #eee;
+    padding-bottom: 1.25rem;
+    margin-bottom: 1.25rem;
+}
+
+.review-section:last-of-type {
+    border-bottom: none;
+}
+
+.review-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-header h4 {
+    margin: 0;
+    color: #333;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: 100px 1fr;
+    gap: 0.25rem 1rem;
+    margin: 0;
+}
+
+.review-section dt {
+    font-weight: 500;
+    color: #666;
+}
+
+.review-section dd {
+    margin: 0;
+}
+
+.review-work-entry {
+    margin-bottom: 0.75rem;
+    padding-left: 0.5rem;
+    border-left: 3px solid #e0e0e0;
+}
+
+.review-dates {
+    font-size: 0.85rem;
+    color: #666;
+}
+
+.review-description {
+    margin: 0.25rem 0 0;
+    font-size: 0.9rem;
+    color: #555;
+}
+
+.review-reference {
+    margin-bottom: 0.5rem;
+}
+
+.review-cover-letter {
+    white-space: pre-wrap;
+    background: #f9f9f9;
+    padding: 1rem;
+    border-radius: 4px;
+    font-size: 0.9rem;
+}
+
+/* Submission Confirmation */
+.submission-confirmation {
+    text-align: center;
+    padding: 2rem;
+}
+
+.submission-confirmation h4 {
+    color: #4caf50;
+    font-size: 1.4rem;
+}
