@namespace sv_ce74dac5d6ec4c60912450a200712cda.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn-remove" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company"
               @onchange="e => { Entry.Company = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title"
               @onchange="e => { Entry.Title = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => { Entry.StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString(\"yyyy-MM-dd\")); NotifyChanged(); }" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")"
                   disabled="@Entry.IsCurrent"
                   @onchange="e => { Entry.EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!); NotifyChanged(); }" />
        </div>
        <div class="form-group checkbox-group">
            <label>
                <input type="checkbox" checked="@Entry.IsCurrent" @onchange="ToggleCurrent" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description"
                  @onchange="e => { Entry.Description = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void NotifyChanged() => OnChanged.InvokeAsync(Entry);

    private void ToggleCurrent(ChangeEventArgs e)
    {
        Entry.IsCurrent = (bool)(e.Value ?? false);
        if (Entry.IsCurrent) Entry.EndDate = null;
        NotifyChanged();
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }
}

